"""Exported UDS test cases (8 tests) - generated by uds_assistant.export.to_pytest.

Request/response bytes are copied verbatim from the TestCase objects (templates +
rules-engine oracle, or the hand-written gold set). The ECU spec is SYNTHETIC.

!!! FOR SIMULATOR OR APPROVED LAB BENCH ONLY. NEVER RUN AGAINST A PRODUCTION VEHICLE. !!!
Safety: the file refuses to run unless the CAN interface is "virtual"
(UDS_CAN_INTERFACE, default "virtual"); set UDS_ALLOW_LAB_BENCH=1 to override on an
approved bench.

Run:   python -m pytest demo_tests_test.py -q
Mode:  UDS_EXPORT_TRANSPORT=inprocess (default) | can  (python-can virtual bus +
       udsoncan PythonIsoTpConnection; tests with time-advance steps are skipped).
Spec:  UDS_SPEC_PATH overrides the spec file (default: <repo>/data/bcm_spec.yaml).
"""

from __future__ import annotations

import itertools
import os
import sys
import time
from pathlib import Path

import pytest


def _ensure_package_importable() -> None:
    try:
        import uds_assistant  # noqa: F401
        return
    except ImportError:
        pass
    candidates = [os.environ.get("UDS_REPO_ROOT", ""), *map(str, Path(__file__).resolve().parents)]
    for root in candidates:
        if root and (Path(root) / "uds_assistant" / "__init__.py").exists():
            sys.path.insert(0, root)
            return
    raise ImportError("uds_assistant not importable; set UDS_REPO_ROOT to the repository root")


CAN_INTERFACE = os.environ.get("UDS_CAN_INTERFACE", "virtual").strip().lower()
if CAN_INTERFACE != "virtual" and os.environ.get("UDS_ALLOW_LAB_BENCH") != "1":
    pytest.exit(
        f"Refusing to run: CAN interface is {CAN_INTERFACE!r}, not 'virtual'. "
        "These tests are for the simulator or an approved lab bench only and must never run "
        "against a production vehicle. On an approved bench set UDS_ALLOW_LAB_BENCH=1.",
        returncode=2,
    )

_ensure_package_importable()

import uds_assistant
from uds_assistant.simulator import EcuCanServer, InProcessTransport, SimulatedEcu
from uds_assistant.spec.schema import load_spec

TRANSPORT = os.environ.get("UDS_EXPORT_TRANSPORT", "inprocess").strip().lower()
SPEC_PATH = Path(
    os.environ.get(
        "UDS_SPEC_PATH",
        str(Path(uds_assistant.__file__).resolve().parents[1] / "data" / "bcm_spec.yaml"),
    )
)
SPEC = load_spec(SPEC_PATH)
CAN_RESPONSE_TIMEOUT_S = 2.0
CAN_SILENCE_WAIT_S = 0.3
_channels = itertools.count()


def _apply_setup(ecu, step):
    if step[0] == "env":
        ecu.set_environment(vehicle_speed_kph=step[1], nvm_write_fault=step[2])
    elif step[0] == "dtc":
        ecu.set_dtc_status(step[1], step[2])


def _check(index, request_hex, expected, actual):
    assert actual == expected, (
        f"step {index}: request {request_hex} expected {expected}, got {actual}"
    )


def _run_inprocess(steps):
    ecu = SimulatedEcu(SPEC)
    transport = InProcessTransport(ecu)
    now_ms = 0
    for index, step in enumerate(steps):
        if step[0] == "send":
            _, request_hex, expected, max_ms = step
            start = time.perf_counter()
            frames = transport.send(bytes.fromhex(request_hex), now_ms=now_ms)
            elapsed_ms = (time.perf_counter() - start) * 1000.0
            _check(index, request_hex, expected, [f.hex() for f in frames])
            if max_ms is not None:
                assert elapsed_ms <= max_ms, f"step {index}: {elapsed_ms:.2f} ms > {max_ms} ms"
        elif step[0] == "advance":
            now_ms += step[1]
        else:
            _apply_setup(ecu, step)


def _can_exchange(conn, request, expect_silence):
    conn.empty_rxqueue()
    conn.send(request)
    frames = []
    timeout = CAN_SILENCE_WAIT_S if expect_silence else CAN_RESPONSE_TIMEOUT_S
    while True:
        frame = conn.wait_frame(timeout=timeout)
        if frame is None:
            return frames
        frame = bytes(frame)
        frames.append(frame)
        if not (len(frame) == 3 and frame[0] == 0x7F and frame[2] == 0x78):
            return frames


def _run_can(steps):
    import can
    from udsoncan.connections import PythonIsoTpConnection

    from uds_assistant.simulator.transport import (
        ECU_TO_TESTER_ID,
        TESTER_TO_ECU_ID,
        make_isotp_stack,
    )

    if any(step[0] == "advance" for step in steps):
        pytest.skip("time-advance step: needs an injected clock (run in inprocess mode)")
    ecu = SimulatedEcu(SPEC)
    channel = f"uds_export_{os.getpid()}_{next(_channels)}_{time.monotonic_ns()}"
    with EcuCanServer(ecu, channel=channel):
        bus = can.Bus(interface=CAN_INTERFACE, channel=channel, receive_own_messages=False)
        notifier = can.Notifier(bus, [], timeout=0.05)
        stack = make_isotp_stack(bus, notifier, rx_id=ECU_TO_TESTER_ID, tx_id=TESTER_TO_ECU_ID)
        conn = PythonIsoTpConnection(stack)
        conn.open()
        try:
            for index, step in enumerate(steps):
                if step[0] == "send":
                    _, request_hex, expected, _max_ms = step
                    frames = _can_exchange(conn, bytes.fromhex(request_hex), not expected)
                    _check(index, request_hex, expected, [f.hex() for f in frames])
                else:
                    _apply_setup(ecu, step)
        finally:
            conn.close()
            notifier.stop()
            bus.shutdown()


def run_steps(steps):
    """Execute one exported test's steps on the selected transport."""
    if TRANSPORT == "can":
        _run_can(steps)
    else:
        _run_inprocess(steps)


def test_req_010__tpl_read_did_positive_0110_01():
    """Read DID driver_door_lock_state (0x0110) positively in session 0x1 [positive; template=read_did_positive; requirements=REQ-010]

    Preconditions: ECU in default session (0x01)
    Pass criteria: ECU replies 62 01 10 01 (positive) within P2 = 50 ms.
    """
    run_steps([
        ('send', '220110', ['62011001'], None),
    ])

def test_req_010__tpl_seed_while_unlocked_03():
    """Seed request while security level 0x3 is already unlocked [security; template=seed_request_while_unlocked; requirements=REQ-010]

    Preconditions: ECU in programming session (0x02); Security level 0x03 unlocked
    Pass criteria: All 6 requests must get exactly the expected bytes. Action under test: ECU replies 67 03 00 00 00 00 (positive) within P2 = 50 ms.
    """
    run_steps([
        ('send', '1002', ['5002003201f4'], None),
        ('send', '2703', ['67030b7ced5e'], None),
        ('send', '270420a92dba', ['6704'], None),
        ('send', '2703', ['670300000000'], None),
        ('send', '2e01600000', ['6e0160'], None),
        ('send', '2703', ['670300000000'], None),
    ])

def test_req_010__tpl_service_not_in_session_27_01():
    """Service 0x27 rejected in session 0x1 [session; template=service_not_in_session; requirements=REQ-010]

    Preconditions: ECU in default session (0x01); No security level unlocked
    Pass criteria: ECU replies 7F 27 7F (serviceNotSupportedInActiveSession) within P2 = 50 ms.
    """
    run_steps([
        ('send', '2701', ['7f277f'], None),
    ])

def test_req_010__tpl_seed_replay_01():
    """Replayed SecurityAccess key for level 0x1 is rejected [security; template=seed_replay_rejected; requirements=REQ-010]

    Preconditions: ECU in extended session (0x03); Security level 0x01 unlocked
    Pass criteria: All 4 requests must get exactly the expected bytes. Action under test: ECU replies 7F 27 24 (requestSequenceError) within P2 = 50 ms.
    """
    run_steps([
        ('send', '1003', ['5003003201f4'], None),
        ('send', '2701', ['6701950677e8'], None),
        ('send', '27029a068f73', ['6702'], None),
        ('send', '27029a068f73', ['7f2724'], None),
    ])

def test_req_010__tpl_security_lockout_01():
    """SecurityAccess level 0x1 lockout after 3 wrong keys [security; template=security_invalid_key_lockout; requirements=REQ-010]

    Preconditions: ECU in extended session (0x03); No security level unlocked; 3 failed key attempt(s) on level 0x01
    Pass criteria: All 10 requests must get exactly the expected bytes. Action under test: ECU replies 67 01 6C DD 4E BF (positive) within P2 = 50 ms.
    """
    run_steps([
        ('send', '1003', ['5003003201f4'], None),
        ('send', '2701', ['6701950677e8'], None),
        ('send', '2702960778e9', ['7f2735'], None),
        ('send', '2701', ['670132a31485'], None),
        ('send', '270233a41586', ['7f2735'], None),
        ('send', '2701', ['6701cf40b122'], None),
        ('send', '2702d041b223', ['7f2736'], None),
        ('send', '2701', ['7f2737'], None),
        ('advance', 10001),
        ('send', '1003', ['5003003201f4'], None),
        ('send', '2701', ['67016cdd4ebf'], None),
    ])

def test_req_010__tpl_read_multi_0110_f190_01():
    """Multi-DID read driver_door_lock_state + VIN in session 0x1 [positive; template=read_multiple_dids; requirements=REQ-010]

    Preconditions: ECU in default session (0x01)
    Pass criteria: ECU replies 62 01 10 01 F1 90 53 59 4E 54 48 45 54 49 43 42 4D 30 30 30 30 30 31 (positive) within P2 = 50 ms.
    """
    run_steps([
        ('send', '220110f190', ['62011001f19053594e544845544943424d303030303031'], None),
    ])

def test_req_010__tpl_read_badlen_0110_01():
    """Malformed-length reads of DID driver_door_lock_state (0x0110) are rejected [negative; template=read_did_invalid_length; requirements=REQ-010]

    Preconditions: ECU in default session (0x01)
    Pass criteria: All 4 requests must get exactly the expected bytes. Action under test: ECU replies 62 01 10 01 (positive) within P2 = 50 ms.
    """
    run_steps([
        ('send', '22', ['7f2213'], None),
        ('send', '2201', ['7f2213'], None),
        ('send', '22011000', ['7f2213'], None),
        ('send', '220110', ['62011001'], None),
    ])

def test_req_010__tpl_session_relock_03():
    """Session change re-locks security level 0x3 [security; template=session_change_relocks_security; requirements=REQ-010]

    Preconditions: ECU in programming session (0x02); No security level unlocked
    Pass criteria: All 6 requests must get exactly the expected bytes. Action under test: ECU replies 67 03 A8 19 8A FB (positive) within P2 = 50 ms.
    """
    run_steps([
        ('send', '1002', ['5002003201f4'], None),
        ('send', '2703', ['67030b7ced5e'], None),
        ('send', '270420a92dba', ['6704'], None),
        ('send', '1002', ['5002003201f4'], None),
        ('send', '2e01600000', ['7f2e33'], None),
        ('send', '2703', ['6703a8198afb'], None),
    ])
